document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".copy-code-btn");e.forEach(e=>{e.addEventListener("click",async()=>{const n=e.closest(".code-container"),t=n.querySelector("pre.ccode");if(t){const n=t.innerText;try{await navigator.clipboard.writeText(n);const t=e.innerHTML;e.innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#4cd964" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="feather feather-check"><polyline points="20 6 9 17 4 12"></polyline></svg>`,e.classList.add("copied"),setTimeout(()=>{e.innerHTML=t,e.classList.remove("copied")},2e3)}catch(e){console.error("Failed to copy: ",e)}}})})})